/** Current or explicit-stage final physical values, exact manager refresh selection, and held Province admission. */
public final class ArmyStrengthsAssaultEligible {
    private ArmyStrengthsAssaultEligible() { }
    public record FinalPhysical(int persistentId,int index,boolean available,Integer current,Integer maximum,Field<Integer> state) {
        public FinalPhysical {require(persistentId!=-1&&index>=0&&index<7,"exact final physical identity/index required");Objects.requireNonNull(state);require(!available||current!=null&&maximum!=null,"available final physical requires current/max");}
    }
    public record Refresh(int regiment,RaisedRegimentRefresh.Result result,List<String> missing) {public Refresh{missing=List.copyOf(missing);}public boolean ready(){return result!=null&&result.ready();}public Integer current(){return result==null?null:result.current();}public Integer maximum(){return result==null?null:result.maximum();}}
    public record TargetRefresh(ArmyStrengthsRefill.RefreshRegiment target,Refresh refresh) { }
    public record RefreshEvent(ArmyStrengthsRefill.RefreshOccurrence observed,List<TargetRefresh> targets) {public RefreshEvent{targets=List.copyOf(targets);}}
    public record Delta(int storedIndex,int regiment,Integer before,Integer after,Integer delta) { }
    public record Occurrence(int storedIndex,int publicUnitId,Boolean admitted,boolean ready,Integer whole,List<Delta> deltas) {public Occurrence{deltas=List.copyOf(deltas);}}
    public record Model(ArmyStrengthsRefill.Besieging original,Integer b,Integer expected,List<Occurrence> occurrences,List<Refresh> refreshed,List<FinalPhysical> physical) {public Model{occurrences=List.copyOf(occurrences);refreshed=List.copyOf(refreshed);physical=List.copyOf(physical);}}
    public record Result(int group,long slot,ArmyStrengths.Status status,boolean ready,Integer b,boolean bReady,Integer expected,boolean expectedReady,Integer nativeB,Integer nativeLoss,Model model,List<Refresh> refreshed,List<RefreshEvent> events,List<FinalPhysical> physical,List<Occurrence> occurrences,ArmyStrengthsAssault.ExpectedLoss arithmetic,List<String> missing,String zeroBasis) {
        public Result {refreshed=List.copyOf(refreshed);events=List.copyOf(events);physical=List.copyOf(physical);occurrences=List.copyOf(occurrences);missing=List.copyOf(missing);}
    }
    private record Selection(boolean ready,List<ArmyStrengthsRefill.RefreshOccurrence> events,List<String> missing) { }
    private static Selection selection(ArmyStrengthsRefill.OrderedBesieging s,ArmyStrengthsRefill.Besieging family){
        if(s==null)return new Selection(false,List.of(),List.of("captured_group_ArRg_refresh_selection"));if(s.provinceId()!=family.provinceId())return new Selection(false,List.of(),List.of("same_group_Province_refresh_selection"));if(!s.refreshMembershipReady())return new Selection(false,List.of(),List.of("complete_group_ArRg_refresh_membership"));
        Integer count=s.physicalScope().nativeArmyRefreshOccurrenceCount();Set<Integer> ids=new HashSet<>(s.targetArmyRegimentIds());if(count==null||count<0||ids.size()!=s.targetArmyRegimentIds().size()||ids.contains(-1))return new Selection(false,List.of(),List.of("well_formed_ordered_group_refresh_selection"));
        Set<Integer> expected=new HashSet<>();for(var o:family.occurrences())if(Boolean.TRUE.equals(o.eligible()))for(var r:o.regiments())if(r.available()&&r.armyRegimentId()!=-1)expected.add(r.armyRegimentId());if(!ids.equals(expected))return new Selection(false,List.of(),List.of("complete_same_group_target_ArRg_identity_set"));
        int previous=-1;for(var event:s.refreshOccurrences()){if(event.managerStoredIndex()<=previous||event.managerStoredIndex()>=count||event.nativeRegimentOccurrenceCount()<0)return new Selection(false,List.of(),List.of("ordered_original_manager_Army_occurrences"));previous=event.managerStoredIndex();int position=-1;for(var target:event.regiments()){if(target.storedIndex()<=position||target.storedIndex()>=event.nativeRegimentOccurrenceCount()||!expected.contains(target.armyRegimentId()))return new Selection(false,List.of(),List.of("ordered_original_target_ArRg_occurrences"));position=target.storedIndex();}}
        return new Selection(true,s.refreshOccurrences(),List.of());
    }
    private static FinalPhysical unavailable(FinalPhysical p){return new FinalPhysical(p.persistentId(),p.index(),false,null,null,new NullValue<>());}
    private static Map<PhysicalKey,FinalPhysical> physical(ArmyStrengthsRefill.Besieging family,List<FinalPhysical> overlay){
        Map<PhysicalKey,FinalPhysical> out=new LinkedHashMap<>();for(var o:family.occurrences())if(Boolean.TRUE.equals(o.eligible()))for(var r:o.regiments())if(r.replenishmentRecords()!=null)for(var d:r.replenishmentRecords().records()){
            PhysicalKey key=new PhysicalKey(d.persistentRegimentId(),d.chunkIndex());FinalPhysical observed=new FinalPhysical(d.persistentRegimentId(),d.chunkIndex(),d.status()==FullDataModel.RecordStatus.AVAILABLE,d.currentSoldiers(),d.maximumSoldiers(),d.stateRaw()==null?new NullValue<>():new Present<>(d.stateRaw()));if(out.containsKey(key)&&!out.get(key).equals(observed))observed=unavailable(observed);out.put(key,observed);
        }
        Map<PhysicalKey,FinalPhysical> supplied=new LinkedHashMap<>();if(overlay!=null)for(FinalPhysical raw:overlay){PhysicalKey key=new PhysicalKey(raw.persistentId(),raw.index());FinalPhysical replacement=raw.available()?raw:unavailable(raw);if(replacement.state() instanceof Missing<Integer>&&out.containsKey(key))replacement=new FinalPhysical(raw.persistentId(),raw.index(),replacement.available(),replacement.current(),replacement.maximum(),out.get(key).state());require(!supplied.containsKey(key)||supplied.get(key).equals(replacement),"conflicting duplicate final physical identity");supplied.put(key,replacement);out.put(key,replacement);}return out;
    }
    private static ArmyStrengthsAssault.ExpectedLoss loss(ArmyStrengthsRefill.Besieging b,Integer current){var c=b.assaultContext();return ArmyStrengthsAssault.expectedLoss(new ArmyStrengthsAssault.ExpectedLossInput(b.provinceId(),ArmyStrengths.Status.valueOf(b.status().name()),c.hasActiveSiege(),c.breachLevelRaw(),c.casualtyPercentageCount(),c.casualtyPercentageRaw(),current));}
    private static Result initial(LossGroup g,List<String> missing){return new Result(g.nativeIndex(),g.slot(),ArmyStrengths.Status.UNAVAILABLE,false,null,false,null,false,null,g.nativeExpectedLoss(),null,List.of(),List.of(),List.of(),List.of(),null,missing,null);}
    public static Result project(LossGroup group,List<FinalPhysical> derived,ArmyStrengthsRefill.OrderedBesieging refreshSelection){
        if(group.provinceMagic()!=null&&group.provinceMagic()!=0x50726f76L)return new Result(group.nativeIndex(),group.slot(),ArmyStrengths.Status.AVAILABLE,true,null,false,0,true,null,group.nativeExpectedLoss(),null,List.of(),List.of(),List.of(),List.of(),null,List.of(),"source_invalid_actual_group_Province_magic");
        var family=group.besieging();if(family==null||!Objects.equals(group.provinceMagic(),0x50726f76L))return initial(group,List.of("actual_group_Province_B_family_and_magic"));Integer count=family.nativeProvinceUnitCount();
        if(count!=null&&count<=0){var arithmetic=loss(family,0);return new Result(group.nativeIndex(),group.slot(),ArmyStrengths.Status.AVAILABLE,true,0,true,0,true,family.nativeBesiegingStrength(),group.nativeExpectedLoss(),new Model(family,0,0,List.of(),List.of(),List.of()),List.of(),List.of(),List.of(),List.of(),arithmetic,List.of(),"nonpositive_original_Province_count");}
        boolean complete=family.contributorsReady()&&count!=null&&count==family.occurrences().size();if(complete)for(int i=0;i<count;i++)complete&=family.occurrences().get(i).storedIndex()==i;
        Selection selected=selection(refreshSelection,family);Map<PhysicalKey,FinalPhysical> physical=physical(family,derived);Map<Integer,ArmyStrengthsRefill.BesiegingRegiment> snapshots=new LinkedHashMap<>();Set<Integer> inconsistent=new HashSet<>();
        for(var o:family.occurrences())if(Boolean.TRUE.equals(o.eligible()))for(var r:o.regiments()){var old=snapshots.get(r.armyRegimentId());if(old!=null&&(!Objects.equals(old.currentSoldiers(),r.currentSoldiers())||!Objects.equals(old.maximumSoldiers(),r.maximumSoldiers())||!Objects.equals(old.replenishmentRecords(),r.replenishmentRecords())))inconsistent.add(r.armyRegimentId());snapshots.putIfAbsent(r.armyRegimentId(),r);}
        Map<Integer,Refresh> after=new LinkedHashMap<>();List<RefreshEvent> receipts=new ArrayList<>();Map<PhysicalKey,ArmyStrengthsAssaultLoss.Physical> typedPhysical=new LinkedHashMap<>();for(var e:physical.entrySet()){FinalPhysical p=e.getValue();Integer state=p.state() instanceof Present<Integer> v?v.value():null;typedPhysical.put(e.getKey(),new ArmyStrengthsAssaultLoss.Physical(e.getKey(),p.current(),p.maximum(),state,!(p.state() instanceof Missing<Integer>)));}
        List<RaisedRegimentRefresh.PhysicalChunk> refreshPhysical=physical.values().stream().map(p->new RaisedRegimentRefresh.PhysicalChunk(p.persistentId(),p.index(),p.current(),p.maximum())).toList();
        if(selected.ready())for(var event:selected.events()){List<TargetRefresh> targets=new ArrayList<>();for(var target:event.regiments()){
            int id=target.armyRegimentId();var observed=snapshots.get(id);FullDataModel.Snapshot data=observed==null?null:observed.replenishmentRecords();Refresh projected=new Refresh(id,null,List.of("complete_selected_target_DATA"));
            if(data!=null&&!inconsistent.contains(id)){if(derived!=null||Boolean.TRUE.equals(data.nativeLossWriterSkipped())){var result=RaisedRegimentRefresh.project(ArmyStrengthsAssaultLoss.refreshSnapshot(data,typedPhysical,true),refreshPhysical);projected=new Refresh(id,result,result.missingInputs());}else projected=new Refresh(id,null,List.of("explicit_final_physical_values"));}
            if(inconsistent.contains(id))projected=new Refresh(id,null,List.of("consistent_same_capture_target_identity"));after.put(id,projected);targets.add(new TargetRefresh(target,projected));
        }receipts.add(new RefreshEvent(event,targets));}
        boolean bReady=complete&&selected.ready();int total=0;List<Occurrence> occurrences=new ArrayList<>();for(var o:family.occurrences()){
            boolean ready=Boolean.FALSE.equals(o.eligible());Integer current=ready?0:o.nativeWholeCurrentSoldiers();List<Delta> deltas=new ArrayList<>();if(Boolean.TRUE.equals(o.eligible())){ready=current!=null;for(var r:o.regiments()){Refresh projected=after.get(r.armyRegimentId());if(projected!=null){boolean valid=projected.ready()&&r.currentSoldiers()!=null;Integer delta=valid?projected.current()-r.currentSoldiers():null;ready&=valid;deltas.add(new Delta(r.storedIndex(),r.armyRegimentId(),r.currentSoldiers(),projected.current(),delta));if(valid&&current!=null)current+=delta;}}}
            bReady&=ready;if(ready)total+=current;occurrences.add(new Occurrence(o.storedIndex(),o.publicUnitId(),o.eligible(),ready,ready?current:null,deltas));
        }
        Integer b=bReady?total:null;List<String> missing=new ArrayList<>(selected.missing());if(!bReady)missing.add("complete_group_B_occurrences_and_selected_refresh_values");var arithmetic=loss(family,b);missing.addAll(arithmetic.missingInputs());boolean ready=bReady&&arithmetic.ready();List<FinalPhysical> physicalList=new ArrayList<>(physical.values());List<Refresh> refreshed=new ArrayList<>(after.values());Model model=ready?new Model(family,b,arithmetic.conditionalExpectedLoss(),occurrences,refreshed,physicalList):null;
        return new Result(group.nativeIndex(),group.slot(),ready?ArmyStrengths.Status.AVAILABLE:ArmyStrengths.Status.PARTIAL,ready,b,bReady,arithmetic.conditionalExpectedLoss(),arithmetic.ready(),family.nativeBesiegingStrength(),group.nativeExpectedLoss(),model,refreshed,receipts,physicalList,occurrences,arithmetic,new ArrayList<>(new LinkedHashSet<>(missing)),null);
    }
    static ObjectNode emitRefresh(Refresh r){if(r.result()!=null)return ArmyJson.object(ArmyStrengthsCodec.parseValue(new org.xar.ck3.control.application.action.RawJson(ArmySelectorCodec.encodeRefresh(r.result()))));ObjectNode n=empty().put("army_regiment_id",r.regiment()).put("current_maximum_ready",false).putNull("current_soldiers").putNull("maximum_soldiers");ArrayNode missing=n.putArray("missing_inputs");r.missing().forEach(missing::add);return n;}
    static ObjectNode emitPhysical(FinalPhysical p){ObjectNode n=empty().put("persistent_regiment_id",p.persistentId()).put("chunk_index",p.index()).put("status",p.available()?"available":"unavailable");put(n,"current_soldiers",p.current());put(n,"maximum_soldiers",p.maximum());if(p.state() instanceof Present<Integer> v)put(n,"state_raw",v.value());else if(p.state() instanceof NullValue<Integer>)n.putNull("state_raw");return n;}
    static ObjectNode emitModel(Model model){if(model==null)return null;ObjectNode n=ArmyJson.object(ArmyStrengthsRefill.encodeBesieging(model.original()));put(n,"native_besieging_strength",model.b());put(n,"native_assault_expected_loss",model.expected());Map<Integer,Refresh> refreshed=new LinkedHashMap<>();model.refreshed().forEach(r->refreshed.put(r.regiment(),r));Map<PhysicalKey,FinalPhysical> physical=new LinkedHashMap<>();model.physical().forEach(p->physical.put(new PhysicalKey(p.persistentId(),p.index()),p));
        for(int i=0;i<model.original().occurrences().size();i++){var original=model.original().occurrences().get(i);ObjectNode row=ArmyJson.object(n.get("occurrences").get(i));if(!Boolean.TRUE.equals(original.eligible()))continue;if(i<model.occurrences().size()&&model.occurrences().get(i).ready())put(row,"native_whole_current_soldiers",model.occurrences().get(i).whole());
            for(int j=0;j<original.regiments().size();j++){var r=original.regiments().get(j);ObjectNode regiment=ArmyJson.object(row.get("regiments").get(j));Refresh refresh=refreshed.get(r.armyRegimentId());if(refresh!=null&&refresh.ready()&&r.currentSoldiers()!=null){put(regiment,"current_soldiers",refresh.current());put(regiment,"maximum_soldiers",refresh.maximum());}if(r.replenishmentRecords()!=null)for(int k=0;k<r.replenishmentRecords().records().size();k++){var record=r.replenishmentRecords().records().get(k);FinalPhysical p=physical.get(new PhysicalKey(record.persistentRegimentId(),record.chunkIndex()));if(p==null)continue;ObjectNode out=ArmyJson.object(regiment.get("replenishment_records_v1").get("records").get(k));Integer state=p.state() instanceof Missing<Integer>?record.stateRaw():p.state() instanceof Present<Integer> v?v.value():null;put(out,"current_soldiers",p.current());put(out,"maximum_soldiers",p.maximum());put(out,"state_raw",state);put(out,"effective_current_soldiers",Objects.equals(state,3)&&Objects.equals(p.current(),0)?p.maximum():p.current());}
        }}return n;
    }
    public static ObjectNode encode(Result r){ObjectNode n=empty().put("projection_kind","conditional_assault_eligible_contributors_12004").put("source_contract_game_version","1.20.0.4").put("group_native_index",r.group()).put("physical_slot_i64",r.slot()).put("status",r.status().name().toLowerCase(java.util.Locale.ROOT)).put("ready",r.ready()).put("conditional_besieging_strength_ready",r.bReady()).put("expected_loss_ready",r.expectedReady()).put("model_operands_rebased",r.model()!=null).put("refill_ADDs",0).put("physical_core_invocations",0).put("input_basis","explicit_final_physical_values; captured_ordered_target_refresh_selection; fixed_actual_group_Province_Unit_Army_admission_and_Siege_context");put(n,"conditional_besieging_strength",r.b());put(n,"expected_loss",r.expected());put(n,"native_besieging_strength",r.nativeB());put(n,"native_current_expected_loss",r.nativeLoss());n.set("besieging_inputs_v1",emitModel(r.model()));ArrayNode refreshed=n.putArray("final_refreshed_regiments");r.refreshed().forEach(x->refreshed.add(emitRefresh(x)));ArrayNode events=n.putArray("refresh_occurrences");for(RefreshEvent e:r.events()){var o=e.observed();ObjectNode row=events.addObject().put("manager_stored_index",o.managerStoredIndex()).put("raw_carmy_id",o.rawCarmyId()).put("resolved_carmy_id",o.resolvedCarmyId()).put("army_used_fallback",o.armyUsedFallback()).put("native_regiment_occurrence_count",o.nativeRegimentOccurrenceCount());ArrayNode targets=row.putArray("regiments");for(TargetRefresh t:e.targets()){ObjectNode q=targets.addObject().put("stored_index",t.target().storedIndex()).put("raw_army_regiment_id",t.target().rawArmyRegimentId()).put("army_regiment_id",t.target().armyRegimentId());q.set("refresh",emitRefresh(t.refresh()));}}
        ArrayNode physical=n.putArray("conditional_physical_chunks");r.physical().forEach(p->physical.add(emitPhysical(p)));ArrayNode occurrences=n.putArray("besieging_occurrences");for(Occurrence o:r.occurrences()){ObjectNode row=occurrences.addObject().put("stored_index",o.storedIndex()).put("public_unit_id",o.publicUnitId()).put("ready",o.ready());put(row,"admitted",o.admitted());put(row,"conditional_whole_current_soldiers",o.whole());ArrayNode deltas=row.putArray("deltas");for(Delta d:o.deltas()){ObjectNode q=deltas.addObject().put("stored_index",d.storedIndex()).put("army_regiment_id",d.regiment());put(q,"before_current",d.before());put(q,"after_current",d.after());put(q,"delta_i32",d.delta());}}n.set("assault_projection",r.arithmetic()==null?null:r.arithmetic().toJson());ArrayNode missing=n.putArray("missing_inputs");r.missing().forEach(missing::add);if(r.zeroBasis()!=null)n.put("zero_basis",r.zeroBasis());n.putNull("actual_post_stage");for(String f:List.of("actual_replenishment","actual_loss","actual_effects","full_daily_assault_ready","full_monthly_ready"))n.put(f,false);return n;
    }
}
